export function getPhase(id: string) { return phases.find(p => p.id === id); }

export function getLesson(pid: string, lid: string) {
  const p = getPhase(pid);
  return p ? { lesson: p.lessons.find(l => l.id === lid), phase: p } : undefined;
}

export function getTotalLessons() { return 435; }

export function getAllLessons() {
  return phases.flatMap(p => p.lessons.map(l => ({ lesson: l, phase: p })));
}
